{"code": "import numpy as np, importlib.util
spec=importlib.util.spec_from_file_location('nominal','nominal.py'); nom=importlib.util.module_from_spec(spec); spec.loader.exec_module(nom)
def resp(L,f=45,a=.15*9.81):
    d=dict(length_mm=L,width_mm=10,substrate_mm=.15,piezo_layer_mm=.12,tip_mass_g=4.65,damping_ratio=.015)
    b=nom.beam(d); w=2*np.pi*f; F=b['forcing_mass']*a
    x=F/(b['k']-b['m']*w**2+1j*b['c']*w); v=b['theta']*x/b['cp']; return b,abs(x),abs(v)
def metrics(L,factor):
    b,x,v=resp(L*factor); stress=b['stress_per_m']*x
    return x*1e6,v,stress/1e6,1-stress/13.75e6,1-x/740e-6
for L in [30.2,30.5,30.8,31.0,31.2,31.5]:
    print('nominal L',L)
    for factor in [0.97,0.98,0.99,1.0,1.01,1.02,1.03,1.05]:
        x,v,s,ss,ts=metrics(L,factor)
        print(f'  f {factor:.2f}: x {x:.0f}um v {v:.2f} stress {s:.1f}MPa sslack {ss:.2f} tslack {ts:.2f}')
